    const ans = BigInt(c1) + BigInt(c2) * (x - 1n) * (x - 1n);
    console.log(ans.toString());
    process.exit(0);
}

// General case: we can form groups of size 2 (one adult + one pupil) and
// groups of size 1 (single adult). Larger groups are never cheaper than
// splitting into 1s and 2s under this pricing.
const pairs = Math.min(adults, pupils);
const remainingAdults = adults - pairs;

// cost for each pair group (size 2): c1 + c2 * (2 - 1)^2 = c1 + c2
