let adults = 0;
let pupils = 0;

for (let i = 0; i < n; i++) {
    if (s[i] === '1') adults++;
    else pupils++;
}

// Cost function: c1 + c2 * (x - 1)^2
function cost(x) {
    const t = x - 1;
    return c1 + c2 * t * t;
}

// If there are no pupils, just group all adults together
if (pupils === 0) {
    console.log(cost(adults).toString());
    process.exit(0);
}

// Try all possible numbers of groups k (1..adults) that can host all pupils
// Each group must contain at least one adult, so k <= adults
// Each group must contain at least one pupil, so k <= pupils
const maxK = Math.min(adults, pupils);
let best = Infinity;

for (let k = 1; k <= maxK; k++) {
    // Each group has at least one pupil: k pupils used
    // Remaining pupils to distribute: pupils - k
    // Adults: at least one per group: k adults used
    // Remaining adults to distribute: adults - k

    const remP = pupils - k;
    const remA = adults - k;

    // Total extra people to distribute among k groups
    const extra = remP + remA;

    // Distribute extra people as evenly as possible:
    // group sizes: base = 2 + floor(extra/k) or 2 + ceil(extra/k)
    const baseExtra = Math.floor(extra / k);
    const biggerGroups = extra % k; // number of groups with baseExtra+1 extra

    const sizeSmall = 2 + baseExtra;
    const sizeBig = sizeSmall + 1;

    const totalCost =
        biggerGroups * cost(sizeBig) +
        (k - biggerGroups) * cost(sizeSmall);

    if (totalCost < best) best = totalCost;
}

