const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/);
let idx = 0;
const n = parseInt(input[idx++], 10);
const c1 = parseInt(input[idx++], 10);
const c2 = parseInt(input[idx++], 10);
const s = input[idx++] || '';

let adults = 0;
let pupils = 0;
for (let i = 0; i < n; i++) {
    if (s[i] === '1') adults++;
    else pupils++;
}

// Precompute cost for group sizes up to n
const cost = new Array(n + 1);
for (let x = 1; x <= n; x++) {
    const diff = x - 1;
    cost[x] = c1 + c2 * diff * diff;
}

// dp[a][p] = minimal cost to serve a adults and p pupils
const INF = BigInt('9000000000000000000000000000000');
const dp = Array.from({ length: adults + 1 }, () =>
    Array(pupils + 1).fill(INF)
);
dp[0][0] = 0n;

for (let a = 0; a <= adults; a++) {
    for (let p = 0; p <= pupils; p++) {
        const cur = dp[a][p];
        if (cur === INF) continue;
        // group size x, with at least one adult: k adults, x-k pupils
        // k from 1..a, x-k from 0..p
        // So x ranges from 1..(a+p)
        const maxX = a + p;
        for (let x = 1; x <= maxX; x++) {
            const maxAdultsInGroup = Math.min(a, x);
            const minAdultsInGroup = Math.max(1, x - p);
            if (minAdultsInGroup > maxAdultsInGroup) continue;
            // We can choose any k in [minAdultsInGroup, maxAdultsInGroup],
            // but result only depends on x, so just pick one feasible k.
            const k = minAdultsInGroup;
            const na = a - k;
            const np = p - (x - k);
            const newCost = cur + BigInt(cost[x]);
            if (newCost < dp[na][np]) dp[na][np] = newCost;
        }
    }
}

